#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#if defined(__AVX512F__)
#define VL 16
#define NV 2
#define MR 14
#define MC (MR * 8)
#define NCB 12
#elif defined(__AVX__)
#define VL 8
#define NV 2
#define MR 6
#define MC (MR * 16)
#define NCB 24
#elif defined(__aarch64__) || defined(__ARM_NEON)
#define VL 4
#define NV 3
#define MR 8
#define MC (MR * 12)
#define NCB 32
#else
#define VL 4
#define NV 2
#define MR 4
#define MC (MR * 16)
#define NCB 32
#endif

#define NR (VL * NV)
#define NC (NR * NCB)
#define KC 256

#define STR(x) #x
#define UNROLL(n) _Pragma(STR(GCC unroll n))

typedef float vf __attribute__((vector_size(VL * 4)));
typedef float vfu __attribute__((vector_size(VL * 4), aligned(4)));

static inline void cpu_relax(void)
{
#if defined(__x86_64__) || defined(__i386__)
    __builtin_ia32_pause();
#elif defined(__aarch64__)
    __asm__ __volatile__("yield");
#endif
}

/* ---------------- microkernel ---------------- */

static inline __attribute__((always_inline))
void kernel(int kc, const float *restrict a, const float *restrict b,
            float *restrict c, int ldc, int mr, int nr, int first)
{
    vf acc[MR][NV];
    UNROLL(16)
    for (int i = 0; i < MR; i++)
        UNROLL(4)
        for (int v = 0; v < NV; v++)
            acc[i][v] = (vf){0};

    UNROLL(16)
    for (int i = 0; i < MR; i++)
        __builtin_prefetch(c + (size_t)i * ldc, 1, 3);

    UNROLL(4)
    for (int p = 0; p < kc; p++) {
        vf bv[NV];
        UNROLL(4)
        for (int v = 0; v < NV; v++)
            bv[v] = *(const vf *)(b + v * VL);
        UNROLL(16)
        for (int i = 0; i < MR; i++) {
            float ai = a[i];
            UNROLL(4)
            for (int v = 0; v < NV; v++)
                acc[i][v] += ai * bv[v];
        }
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
        if (first) {
            UNROLL(16)
            for (int i = 0; i < MR; i++)
                UNROLL(4)
                for (int v = 0; v < NV; v++)
                    *(vfu *)(c + (size_t)i * ldc + v * VL) = acc[i][v];
        } else {
            UNROLL(16)
            for (int i = 0; i < MR; i++)
                UNROLL(4)
                for (int v = 0; v < NV; v++)
                    *(vfu *)(c + (size_t)i * ldc + v * VL) += acc[i][v];
        }
    } else {
        float t[MR][NR] __attribute__((aligned(64)));
        UNROLL(16)
        for (int i = 0; i < MR; i++)
            UNROLL(4)
            for (int v = 0; v < NV; v++)
                *(vf *)&t[i][v * VL] = acc[i][v];
        for (int i = 0; i < mr; i++) {
            float *cr = c + (size_t)i * ldc;
            if (first)
                for (int j = 0; j < nr; j++) cr[j] = t[i][j];
            else
                for (int j = 0; j < nr; j++) cr[j] += t[i][j];
        }
    }
}

/* ---------------- job state ---------------- */

static struct {
    const float *A, *B;
    float *C;
    float *Ap, *Bp;
    int n, mpad, npad, sA, sB, total1, nic, njc, total2;
} J;

static int next1, done1, next2;

/* Pack row strip s of A (MR rows, all k), blocked by KC. */
static void pack_A_strip(int s)
{
    const float *A = J.A;
    int n = J.n, i0 = s * MR;
    int h = n - i0 < MR ? n - i0 : MR;
    const float *rows[MR];
    for (int r = 0; r < MR; r++)
        rows[r] = A + (size_t)(i0 + (r < h ? r : 0)) * n;

    for (int pc = 0; pc < n; pc += KC) {
        int kc = n - pc < KC ? n - pc : KC;
        float *dst = J.Ap + (size_t)pc * J.mpad + (size_t)i0 * kc;
        if (h == MR) {
            for (int p = 0; p < kc; p++) {
                UNROLL(16)
                for (int r = 0; r < MR; r++)
                    dst[r] = rows[r][pc + p];
                dst += MR;
            }
        } else {
            for (int p = 0; p < kc; p++) {
                int r = 0;
                for (; r < h; r++) dst[r] = rows[r][pc + p];
                for (; r < MR; r++) dst[r] = 0.0f;
                dst += MR;
            }
        }
    }
}

/* Pack column strip t of B (NR cols, all k), blocked by KC. */
static void pack_B_strip(int t)
{
    const float *B = J.B;
    int n = J.n, j0 = t * NR;
    int w = n - j0 < NR ? n - j0 : NR;

    for (int pc = 0; pc < n; pc += KC) {
        int kc = n - pc < KC ? n - pc : KC;
        float *dst = J.Bp + (size_t)pc * J.npad + (size_t)j0 * kc;
        const float *src = B + (size_t)pc * n + j0;
        if (w == NR) {
            for (int p = 0; p < kc; p++) {
                UNROLL(4)
                for (int v = 0; v < NV; v++)
                    *(vf *)(dst + v * VL) = *(const vfu *)(src + v * VL);
                dst += NR;
                src += n;
            }
        } else {
            for (int p = 0; p < kc; p++) {
                int j = 0;
                for (; j < w; j++) dst[j] = src[j];
                for (; j < NR; j++) dst[j] = 0.0f;
                dst += NR;
                src += n;
            }
        }
    }
}

static void compute_tile(int t)
{
    int n = J.n;
    int icb = t % J.nic, jcb = t / J.nic;
    int i0 = icb * MC, i1 = i0 + MC < n ? i0 + MC : n;
    int j0 = jcb * NC, j1 = j0 + NC < n ? j0 + NC : n;

    for (int pc = 0; pc < n; pc += KC) {
        int kc = n - pc < KC ? n - pc : KC;
        int first = (pc == 0);
        const float *Ablk = J.Ap + (size_t)pc * J.mpad;
        const float *Bblk = J.Bp + (size_t)pc * J.npad;
        for (int jr = j0; jr < j1; jr += NR) {
            int nr = j1 - jr < NR ? j1 - jr : NR;
            const float *bs = Bblk + (size_t)jr * kc;
            for (int ir = i0; ir < i1; ir += MR) {
                int mr = i1 - ir < MR ? i1 - ir : MR;
                kernel(kc, Ablk + (size_t)ir * kc, bs,
                       J.C + (size_t)ir * n + jr, n, mr, nr, first);
            }
        }
    }
}

static void do_work(void)
{
    int total1 = J.total1, total2 = J.total2, sA = J.sA;
    for (;;) {
        int t = __atomic_fetch_add(&next1, 1, __ATOMIC_RELAXED);
        if (t >= total1) break;
        if (t < sA) pack_A_strip(t);
        else pack_B_strip(t - sA);
        __atomic_fetch_add(&done1, 1, __ATOMIC_RELEASE);
    }
    while (__atomic_load_n(&done1, __ATOMIC_ACQUIRE) < total1)
        cpu_relax();
    for (;;) {
        int t = __atomic_fetch_add(&next2, 1, __ATOMIC_RELAXED);
        if (t >= total2) break;
        compute_tile(t);
    }
}

/* ---------------- persistent thread pool ---------------- */

#define MAXT 256
#define IDLE_SPIN (1 << 16)

static pthread_mutex_t pool_mtx = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t pool_start = PTHREAD_COND_INITIALIZER;
static pthread_cond_t pool_done = PTHREAD_COND_INITIALIZER;
static unsigned pool_gen;
static int pool_pending;
static int pool_n = -1;

static void *pool_worker(void *arg)
{
    (void)arg;
    unsigned my_gen = 0;
    for (;;) {
        unsigned g;
        int spins = 0;
        while ((g = __atomic_load_n(&pool_gen, __ATOMIC_ACQUIRE)) == my_gen &&
               spins < IDLE_SPIN) {
            cpu_relax();
            spins++;
        }
        if (g == my_gen) {
            pthread_mutex_lock(&pool_mtx);
            while ((g = __atomic_load_n(&pool_gen, __ATOMIC_ACQUIRE)) == my_gen)
                pthread_cond_wait(&pool_start, &pool_mtx);
            pthread_mutex_unlock(&pool_mtx);
        }
        my_gen = g;
        do_work();
        if (__atomic_sub_fetch(&pool_pending, 1, __ATOMIC_ACQ_REL) == 0) {
            pthread_mutex_lock(&pool_mtx);
            pthread_cond_signal(&pool_done);
            pthread_mutex_unlock(&pool_mtx);
        }
    }
    return NULL;
}

static void pool_init(void)
{
    long ncpu = sysconf(_SC_NPROCESSORS_ONLN);
    if (ncpu < 1) ncpu = 1;
    if (ncpu > MAXT) ncpu = MAXT;
    pool_n = 0;
    for (long i = 1; i < ncpu; i++) {
        pthread_t th;
        if (pthread_create(&th, NULL, pool_worker, NULL) != 0) break;
        pthread_detach(th);
        pool_n++;
    }
}

static void run_parallel(void)
{
    if (pool_n < 0) pool_init();
    if (pool_n == 0) {
        do_work();
        return;
    }
    __atomic_store_n(&pool_pending, pool_n, __ATOMIC_RELAXED);
    pthread_mutex_lock(&pool_mtx);
    __atomic_add_fetch(&pool_gen, 1, __ATOMIC_RELEASE);
    pthread_cond_broadcast(&pool_start);
    pthread_mutex_unlock(&pool_mtx);

    do_work();

    int spins = 0;
    while (__atomic_load_n(&pool_pending, __ATOMIC_ACQUIRE) != 0 && spins < IDLE_SPIN) {
        cpu_relax();
        spins++;
    }
    if (__atomic_load_n(&pool_pending, __ATOMIC_ACQUIRE) != 0) {
        pthread_mutex_lock(&pool_mtx);
        while (__atomic_load_n(&pool_pending, __ATOMIC_ACQUIRE) != 0)
            pthread_cond_wait(&pool_done, &pool_mtx);
        pthread_mutex_unlock(&pool_mtx);
    }
}

/* ---------------- buffers ---------------- */

static float *bufA, *bufB;
static size_t capA, capB;

static int ensure(float **buf, size_t *cap, size_t need)
{
    if (*cap >= need) return 1;
    free(*buf);
    *buf = NULL;
    *cap = 0;
    void *p = NULL;
    if (posix_memalign(&p, 64, need * sizeof(float))) return 0;
    *buf = (float *)p;
    *cap = need;
    return 1;
}

static void naive(const float *A, const float *B, float *C, int n)
{
    for (int i = 0; i < n; i++) {
        float *ci = C + (size_t)i * n;
        for (int j = 0; j < n; j++) ci[j] = 0.0f;
        for (int k = 0; k < n; k++) {
            float a = A[(size_t)i * n + k];
            const float *bk = B + (size_t)k * n;
            for (int j = 0; j < n; j++) ci[j] += a * bk[j];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    int mpad = (n + MR - 1) / MR * MR;
    int npad = (n + NR - 1) / NR * NR;
    if (!ensure(&bufA, &capA, (size_t)n * mpad) ||
        !ensure(&bufB, &capB, (size_t)n * npad)) {
        naive(A, B, C, n);
        return;
    }

    J.A = A; J.B = B; J.C = C;
    J.Ap = bufA; J.Bp = bufB;
    J.n = n; J.mpad = mpad; J.npad = npad;
    J.sA = mpad / MR;
    J.sB = npad / NR;
    J.total1 = J.sA + J.sB;
    J.nic = (n + MC - 1) / MC;
    J.njc = (n + NC - 1) / NC;
    J.total2 = J.nic * J.njc;
    next1 = 0; done1 = 0; next2 = 0;

    if ((double)n * n * n < 1.5e6)
        do_work();
    else
        run_parallel();
}
